script:
country_event = {
	id = anomaly.3094
	title = anomaly.3094.name
	desc = anomaly.3094.desc
	show_sound = event_conversation
	diplomatic = yes

	is_triggered_only = yes

	picture_event_data = {
		room = no_video_feed_room
	}

	immediate = {
		set_country_flag = captive_rescue
		#owner_species = { save_event_target_as = owner_species }
		if = {
			limit = {
				any_system = {
					distance = {
						source = event_target:buoy
						use_bypasses = no
						min_jumps = 1
						max_jumps = 6
					}
					NOR = {
						exists = space_owner
						has_star_flag = hostile_system
						any_fleet_in_system = { always = yes }
					}
					any_system_planet = { is_asteroid = yes }
				}
			}
			random_system = {
				limit = {
					distance = {
						source = event_target:buoy
						use_bypasses = no
						min_jumps = 1
						max_jumps = 6
					}
					NOR = {
						exists = space_owner
						has_star_flag = hostile_system
						any_fleet_in_system = { always = yes }
					}
					any_system_planet = { is_asteroid = yes }
				}
				set_star_flag = ransomeer_system
				save_event_target_as = the_ransomeer_system
			}
		}
		else = {
			random_system = {
				limit = {
					distance = {
						source = event_target:buoy
						use_bypasses = no
						min_jumps = 1
						max_jumps = 6
					}
					is_owned_by = ROOT
					any_system_planet = { is_asteroid = yes }
				}
				set_star_flag = ransomeer_system
				save_event_target_as = the_ransomeer_system
			}
		}
		event_target:the_ransomeer_system = {
			random_system_planet = {
				limit = { is_asteroid = yes }
				save_event_target_as = ransomeer_asteroid
			}
			create_country = {
				name = "NAME_Ransomeers"
				type = faction
				name_list = "PRT1"
				auto_delete = no
			}
			last_created_country = {
				save_event_target_as = ransomeer
				set_country_flag = ransomeer_flag
				establish_communications_no_message = root
				create_fleet = {
					name = "NAME_Ransomeer_Base"
					effect = {
						save_event_target_as = ransomeer_base
						set_owner = prev
						create_ship = {
							name = "NAME_Ingrates_Inferno"
							design = "NAME_Pirate_Nest"
							graphical_culture = "pirate_01"
						}
						set_location = event_target:ransomeer_asteroid
						set_fleet_flag = ransomeer_base_flag
					}
				}
				create_leader = {
					class = commander
					species = root.owner_species
					name = random
					skill = 2
				}
				create_fleet = {
					name = "NAME_Ransomeers"
					effect = {
						set_owner = PREV
						create_ship_design = {
							design = "NAME_Reaver"
						}
						create_ship = {
							name = random
							design = last_created_design
							graphical_culture = "pirate_01"
						}
						create_ship = {
							name = random
							design = last_created_design
							graphical_culture = "pirate_01"
						}
						create_ship = {
							name = random
							design = last_created_design
							graphical_culture = "pirate_01"
						}
						create_ship = {
							name = random
							design = last_created_design
							graphical_culture = "pirate_01"
						}
						create_ship = {
							name = random
							design = last_created_design
							graphical_culture = "pirate_01"
						}
						assign_leader = last_created_leader
						set_location = event_target:ransomeer_asteroid
					}
				}
			}
		}
		set_relation_flag = {
			who = event_target:ransomeer
			flag = ransomeer_relation
		}
	}

	option = {
		name = anomaly.3094.a
		begin_event_chain = {
			event_chain = "ransomeer_chain"
			target = root
		}
		hidden_effect = {
			create_point_of_interest = {
				id = ransomeer_poi
				name = ransomeer_poi_title
				desc = ransomeer_poi_desc
				event_chain = ransomeer_chain
				location = event_target:ransomeer_base
			}
		}
	}
}

